  ],
  "prediction_basis_card_ids": [
    "C01", "C05", "C08", "C16", "C19", "C22", "C31"
  ],
  "claims": [
    {
      "claim": "The query is structurally an aryloxypropanolamine beta-blocker with a tert-butylamino group and a para-cyclohexylurea; the closest visible beta-blocker contexts report direct absolute oral F values all at or above 27% (CP-331,684 27%; diacetolol 30-43%; celiprolol 30-70%; almokalant ~50%; betaxolol 80-89%; practolol ~100%; pamatolol 64.9-150.5%).",
      "card_ids": ["C16", "C01", "C02", "C03", "C07", "C08", "C09", "C19", "C05", "C22", "C23", "C31", "C34", "C38"]
    },
    {
      "claim": "L2 records add further human F/RBA values >=30% for the same beta-blocker contexts (betaxolol 80-89%, celiprolol 50-74%, pamatolol 90-150%, diacetolol 30-42%, practolol ~100%, CP-331,684 oral solution RBA 100%), reinforcing that the class context supports F >= 20%.",
      "card_ids": ["C43", "C45", "C47", "C50", "C53", "C55", "C60", "C70", "C74", "C75", "C76", "C78", "C80", "C81", "C82"]
    },
    {
      "claim": "The only sub-20% absolute F records are rat data for CP-409,092 (2.9 ± 3%), but the same compound had human RBA 69 ± 33% and the rat result was associated with high plasma clearance; these records are not transferable to the query.",
      "card_ids": ["C06", "C61", "C64", "C66", "C71"]
    },
    {
      "claim": "C42 and C56 show transporter-mediated processes can markedly reduce celiprolol F (grapefruit juice decreased it by 87%; intestinal secretion explains nonlinear F), but they involve a different molecule and a different modifier and do not quantify rifampin's effect on the query.",
      "card_ids": ["C42", "C56"]
    },
    {
      "claim": "No visible card reports a direct F < 20% outcome for the query under rifampin; the external condition is an unquantified modifier, so the positive class remains better supported.",
      "card_ids": []
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C43", "C45", "C47", "C50", "C53", "C55", "C60", "C70", "C74", "C75", "C76", "C78", "C80", "C81", "C82"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C42", "C56", "C61", "C64", "C66", "C71"]
    }
  ],
  "evidence_gaps": [
    "No direct talinolol absolute oral bioavailability measurement under rifampin co-treatment is present in the visible records.",
    "The magnitude of rifampin-mediated P-gp/CYP induction on this exact molecule is not quantified in any card.",
    "No experimental solubility or permeability data for the query are supplied.",
    "Repeated records from the same parent context are not independent votes.",
    "The celiprolol grapefruit-juice interaction is not directly transferable to rifampin/talinolol."
  ],
  "decision_summary": "The query is structurally a beta-blocker closely related to contexts with direct absolute oral F values all >=27%; L2 adds further human F/RBA values >=30%. The only sub-20% records are rat data with low transferability, and no card affirmatively shows F < 20% under rifampin, so the positive class is better supported."
}

